679	    t.cursor_h.run(
680	        &t.loop,
681	        &t.cursor_c,
682	        cursorBlinkInterval(),
683	        Thread,
684	        t,
685	        cursorTimerCallback,
686	    );
687	    return .disarm;
688	}
