367	    /// Destroy callback for `GdkDmabufTexture`. GDK calls this when the
368	    /// texture is released; we close the FDs and free the holder.
369	    fn dmabufDestroy(data: ?*anyopaque) callconv(.c) void {
370	        const app = Application.default();
371	        const alloc = app.allocator();
372	
373	        const planes: *Planes = @ptrCast(@alignCast(data orelse return));
374	        planes.deinit();
375	        alloc.destroy(planes);
376	    }
