 44	pub fn init(opts: Options) !Self {
 45	    // We set our surface's color space to Display P3.
 46	    // This allows us to have "Apple-style" alpha blending,
 47	    // since it seems to be the case that Apple apps like
 48	    // Terminal and TextEdit render text in the display's
 49	    // color space using converted colors, which reduces,
 50	    // but does not fully eliminate blending artifacts.
 51	    const colorspace = try graphics.ColorSpace.createNamed(.displayP3);
 52	    defer colorspace.release();
 53	
 54	    const surface = try IOSurface.init(.{
 55	        .width = @intCast(opts.width),
 56	        .height = @intCast(opts.height),
 57	        .pixel_format = .@"32BGRA",
 58	        .bytes_per_element = 4,
 59	        .colorspace = colorspace,
 60	    });
 61	
 62	    // Create our descriptor
 63	    const desc = init: {
 64	        const Class = objc.getClass("MTLTextureDescriptor").?;
 65	        const id_alloc = Class.msgSend(objc.Object, objc.sel("alloc"), .{});
 66	        const id_init = id_alloc.msgSend(objc.Object, objc.sel("init"), .{});
 67	        break :init id_init;
 68	    };
 69	    defer desc.release();
 70	
 71	    // Set our properties
 72	    desc.setProperty("width", @as(c_ulong, @intCast(opts.width)));
 73	    desc.setProperty("height", @as(c_ulong, @intCast(opts.height)));
 74	    desc.setProperty("pixelFormat", @backingInt(opts.pixel_format));
 75	    desc.setProperty("usage", mtl.MTLTextureUsage{ .render_target = true });
 76	    desc.setProperty(
 77	        "resourceOptions",
 78	        mtl.MTLResourceOptions{
 79	            // Indicate that the CPU writes to this resource but never reads it.
 80	            .cpu_cache_mode = .write_combined,
 81	            .storage_mode = opts.storage_mode,
 82	        },
 83	    );
 84	
 85	    const id = opts.device.msgSend(
 86	        ?*anyopaque,
 87	        objc.sel("newTextureWithDescriptor:iosurface:plane:"),
 88	        .{
 89	            desc,
 90	            surface,
 91	            @as(c_ulong, 0),
 92	        },
 93	    ) orelse return error.MetalFailed;
 94	
 95	    const texture = objc.Object.fromId(id);
 96	
 97	    return .{
 98	        .surface = surface,
 99	        .texture = texture,
100	        .width = opts.width,
101	        .height = opts.height,
102	    };
103	}
