 20	
 21	pub fn init() !IOSurfaceLayer {
 22	    // The layer returned by `[CALayer layer]` is autoreleased, which means
 23	    // that at the end of the current autorelease pool it will be deallocated
 24	    // if it isn't retained, so we retain it here manually an extra time.
 25	    const layer = (try getSubclass()).msgSend(
 26	        objc.Object,
 27	        objc.sel("layer"),
 28	        .{},
 29	    ).retain();
 30	    errdefer layer.release();
 31	
 32	    // The layer gravity is set to top-left so that the contents aren't
 33	    // stretched during resize operations before a new frame has been drawn.
 34	    layer.setProperty("contentsGravity", macos.animation.kCAGravityTopLeft);
 35	
 36	    layer.setInstanceVariable("display_cb", .{ .value = null });
 37	    layer.setInstanceVariable("display_ctx", .{ .value = null });
 38	
 39	    return .{ .layer = layer };
 40	}
