 42	pub fn release(self: *IOSurfaceLayer) void {
 43	    // The layer may be retained by the view after we release our reference.
 44	    // Clear the callback first so that a later display pass can't access the
 45	    // renderer that owned this wrapper after it has been freed.
 46	    self.setDisplayCallback(null, null);
 47	    self.layer.release();
