   217	/// Read the current contents of the framebuffer into CPU memory.
   218	///
   219	/// This is used by the CPU readback presentation fallback. The
   220	/// returned data is tightly-packed RGBA8 with premultiplied alpha,
   221	/// i.e. `width * 4` bytes per row, containing sRGB-encoded values:
   222	/// `GL_FRAMEBUFFER_SRGB` has no effect on `ReadPixels`, so the stored
   223	/// values are returned verbatim.
   224	pub fn readPixelsAlloc(self: *const Self, alloc: std.mem.Allocator) ![]u8 {
   225	    const bind = try self.framebuffer.bind(.read);
   226	    defer bind.unbind();
   227	
   228	    const pixels = try alloc.alloc(u8, self.width * self.height * 4);
   229	    errdefer alloc.free(pixels);
   230	
   231	    try gl.readPixels(
   232	        0,
   233	        0,
   234	        @intCast(self.width),
   235	        @intCast(self.height),
   236	        .rgba,
   237	        .unsigned_byte,
   238	        pixels.ptr,
   239	    );
   240	
   241	    return pixels;
   242	}
