    98	        defer bound_tex.unbind();
    99	        try bound_tex.parameter(.min_filter, .nearest);
   100	        try bound_tex.parameter(.mag_filter, .nearest);
   101	        try bound_tex.parameter(.wrap_s, .clamp_to_edge);
   102	        try bound_tex.parameter(.wrap_t, .clamp_to_edge);
