   104	            0,
   105	            .rgba,
   106	            @intCast(opts.width),
   107	            @intCast(opts.height),
   108	            .rgba,
   109	            .unsigned_byte,
   110	            null,
   111	        );
   112	        try bound_tex.parameter(.base_level, 0);
   113	        try bound_tex.parameter(.max_level, 0);
   114	    }
