   148	pub fn exportDmabuf(
   149	    self: *const Self,
   150	    display: *egl.Display,
   151	    context: *egl.Context,
   152	) !Dmabuf {
   153	    // We disable GL_FRAMEBUFFER_SRGB while doing this blit, otherwise
   154	    // the values may be linearized as they're copied, but even though
   155	    // the draw framebuffer has a linear internal format, the values in
   156	    // it should be sRGB, not linear!
   157	    try gl.disable(gl.c.GL_FRAMEBUFFER_SRGB);
   158	    defer gl.enable(gl.c.GL_FRAMEBUFFER_SRGB) catch |err| {
   159	        log.err("Error re-enabling GL_FRAMEBUFFER_SRGB, err={}", .{err});
   160	    };
   161	
   162	    const read_bind = try self.framebuffer.bind(.read);
   163	    defer read_bind.unbind();
   164	
   165	    const draw_bind = try self.export_framebuffer.bind(.draw);
   166	    defer draw_bind.unbind();
   167	
   168	    try gl.blitFramebuffer(
   169	        0,
   170	        0,
   171	        @intCast(self.width),
   172	        @intCast(self.height),
   173	        0,
   174	        0,
   175	        @intCast(self.width),
   176	        @intCast(self.height),
   177	        .{ .color_buffer_bit = true },
   178	        .nearest,
   179	    );
   180	
   181	    const image: *egl.Image = try .create(
   182	        display,
   183	        context,
   184	        .{ .texture_2d = self.export_texture.id },
   185	        &.{},
   186	    );
   187	    defer image.destroy(display) catch {};
   188	
   189	    const query = try image.exportDmabufQuery(display);
   190	
   191	    if (query.num_planes < 1 or query.num_planes > Dmabuf.max_planes) {
   192	        log.err("DMABUF has too many planes={}", .{query.num_planes});
   193	        return error.DmabufTooManyPlanes;
   194	    }
   195	
   196	    var planes: Dmabuf.Planes = .{ .count = @intCast(query.num_planes) };
   197	    try image.exportDmabuf(
   198	        display,
   199	        &planes.fds,
   200	        &planes.strides,
   201	        &planes.offsets,
   202	    );
   203	    try planes.validate();
   204	
   205	    return .{
   206	        .width = @intCast(self.width),
   207	        .height = @intCast(self.height),
   208	        // bitCast instead of intCast since the numerical value of fourccs
   209	        // is rather meaningless, and we only care about the bit pattern
   210	        .fourcc = @bitCast(query.fourcc),
   211	        .modifier = query.modifier,
   212	        .premultiplied = true,
   213	        .planes = planes,
   214	    };
   215	}
