   678	fragment float4 cell_text_fragment(
   679	  CellTextVertexOut in [[stage_in]],
   680	  texture2d<float> textureGrayscale [[texture(0)]],
   681	  texture2d<float> textureColor [[texture(1)]],
   682	  constant Uniforms& uniforms [[buffer(1)]]
   683	) {
   684	  constexpr sampler textureSampler(
   685	    coord::pixel,
   686	    address::clamp_to_edge,
   687	    filter::nearest
   688	  );
   689	
   690	  switch (in.atlas) {
   691	    default:
   692	    case ATLAS_GRAYSCALE: {
   693	      // Our input color is always linear.
   694	      float4 color = in.color;
   695	
   696	      // If we're not doing linear blending, then we need to
   697	      // re-apply the gamma encoding to our color manually.
   698	      //
   699	      // Since the alpha is premultiplied, we need to divide
   700	      // it out before unlinearizing and re-multiply it after.
   701	      if (!uniforms.use_linear_blending) {
   702	        color.rgb /= color.a;
   703	        color = unlinearize(color);
   704	        color.rgb *= color.a;
   705	      }
   706	
   707	      // Fetch our alpha mask for this pixel.
   708	      float a = textureGrayscale.sample(textureSampler, in.tex_coord).r;
   709	
   710	      // Linear blending weight correction corrects the alpha value to
   711	      // produce blending results which match gamma-incorrect blending.
   712	      if (uniforms.use_linear_correction) {
   713	        // Short explanation of how this works:
   714	        //
   715	        // We get the luminances of the foreground and background colors,
   716	        // and then unlinearize them and perform blending on them. This
   717	        // gives us our desired luminance, which we derive our new alpha
   718	        // value from by mapping the range [bg_l, fg_l] to [0, 1], since
   719	        // our final blend will be a linear interpolation from bg to fg.
   720	        //
   721	        // This yields virtually identical results for grayscale blending,
   722	        // and very similar but non-identical results for color blending.
   723	        float4 bg = in.bg_color;
   724	        float fg_l = luminance(color.rgb);
   725	        float bg_l = luminance(bg.rgb);
   726	        // To avoid numbers going haywire, we don't apply correction
   727	        // when the bg and fg luminances are within 0.001 of each other.
   728	        if (abs(fg_l - bg_l) > 0.001) {
   729	          float blend_l = linearize(unlinearize(fg_l) * a + unlinearize(bg_l) * (1.0 - a));
   730	          a = clamp((blend_l - bg_l) / (fg_l - bg_l), 0.0, 1.0);
   731	        }
   732	      }
   733	
   734	      // Multiply our whole color by the alpha mask.
   735	      // Since we use premultiplied alpha, this is
   736	      // the correct way to apply the mask.
   737	      color *= a;
   738	
   739	      return color;
   740	    }
   741	
   742	    case ATLAS_COLOR: {
   743	      // For now, we assume that color glyphs
   744	      // are already premultiplied linear colors.
   745	      float4 color = textureColor.sample(textureSampler, in.tex_coord);
   746	
   747	      // If we're doing linear blending, we can return this right away.
   748	      if (uniforms.use_linear_blending) {
   749	        return color;
   750	      }
   751	
   752	      // Otherwise we need to unlinearize the color. Since the alpha is
   753	      // premultiplied, we need to divide it out before unlinearizing.
   754	      color.rgb /= color.a;
   755	      color = unlinearize(color);
   756	      color.rgb *= color.a;
   757	
   758	      return color;
   759	    }
   760	  }
   761	}
