318	    fn indexForCell(
319	        self: *RunIterator,
320	        alloc: Allocator,
321	        cell: *const terminal.Cell,
322	        graphemes: []const u21,
323	        style: font.Style,
324	        presentation: ?font.Presentation,
325	    ) !?font.Collection.Index {
326	        if (cell.isEmpty() or
327	            cell.codepoint() == 0 or
328	            cell.codepoint() == terminal.kitty.graphics.unicode.placeholder)
329	        {
330	            return try self.opts.grid.getIndex(
331	                alloc,
332	                ' ',
333	                style,
334	                presentation,
335	            );
336	        }
337	
338	        // Get the font index for the primary codepoint.
339	        const primary_cp: u32 = cell.codepoint();
340	        const primary = try self.opts.grid.getIndex(
341	            alloc,
342	            primary_cp,
343	            style,
344	            presentation,
345	        ) orelse return null;
346	
347	        // Easy, and common: we aren't a multi-codepoint grapheme, so
348	        // we just return whatever index for the cell codepoint.
349	        if (!cell.hasGrapheme()) return primary;
350	
351	        // Try the primary font followed by the font selected for each
352	        // additional codepoint until one supports the entire grapheme.
353	        candidate: for (0..graphemes.len + 1) |i| {
354	            const idx = if (i == 0) primary else idx: {
355	                const cp = graphemes[i - 1];
356	
357	                // Ignore Emoji ZWJs
358	                if (cp == 0xFE0E or cp == 0xFE0F or cp == 0x200D) continue :candidate;
359	
360	                // We explicitly do not require the additional grapheme components
361	                // to support the base presentation, since it is common for emoji
362	                // fonts to support the base emoji with emoji presentation but not
363	                // certain ZWJ-combined characters like the male and female signs.
364	                break :idx try self.opts.grid.getIndex(
365	                    alloc,
366	                    cp,
367	                    style,
368	                    null,
369	                ) orelse return null;
370	            };
371	
372	            if (!self.opts.grid.hasCodepoint(idx, primary_cp, presentation)) continue;
373	            for (graphemes) |cp| {
374	                // Ignore Emoji ZWJs
375	                if (cp == 0xFE0E or cp == 0xFE0F or cp == 0x200D) continue;
376	                if (!self.opts.grid.hasCodepoint(idx, cp, null)) continue :candidate;
377	            }
378	            return idx;
379	        }
380	
381	        return null;
382	    }
383	};
