  2367	        const reach: isize = @as(isize, @intCast(rows)) - 1 + @max(0, vertical_offset);
  2368	        const first = chunks[0];
  2369	        var bottom: isize = first.index - @as(isize, first.start) - 1;
  2370	        var node = first.node.prev;
  2371	        while (node) |n| : (node = n.prev) {
  2372	            if (bottom < -reach) break;
  2373	            const top = bottom - (@as(isize, n.rows()) - 1);
  2374	            if (n == pin.node) return top + pin.y;
  2375	            bottom = top - 1;
  2376	        }
