  2415	                .pin => |pin| .{
  2416	                    .anchor = .{ .pin = pin },
  2417	                    .horizontal_offset = 0,
  2418	                    .vertical_offset = 0,
  2419	                    .placement = template(
  2420	                        storage,
  2421	                        t,
  2422	                        kv.key_ptr.*,
  2423	                        kv.value_ptr,
  2424	                        .fixed,
  2425	                    ) orelse continue,
  2426	                },
  2427	
  2428	                .virtual => continue,
  2429	
  2430	                .relative => |rel| root: {
