  2432	                    // start. A broken chain is never drawn.
  2433	                    const chain = storage.resolveChain(rel) orelse continue;
  2434	                    break :root .{
  2435	                        .anchor = switch (chain.root.location) {
  2436	                            .virtual => .{ .virtual = chain.root_key },
  2437	                            .pin => |pin| .{ .pin = pin },
  2438	
  2439	                            // resolveChain roots are never relative.
  2440	                            .relative => unreachable,
  2441	                        },
  2442	                        .horizontal_offset = chain.horizontal_offset,
  2443	                        .vertical_offset = chain.vertical_offset,
  2444	                        .placement = template(
  2445	                            storage,
  2446	                            t,
  2447	                            kv.key_ptr.*,
  2448	                            kv.value_ptr,
  2449	                            .relative,
  2450	                        ) orelse continue,
  2451	                    };
  2452	                },
  2453	            };
