  2577	    /// Groups Kitty placeholder cells into runs as the row scan visits
  2578	    /// them. Feed it placeholder cells from left to right. A gap between
  2579	    /// two cells (any cell that isn't fed) ends the current run.
  2580	    const PlaceholderDecoder = struct {
  2581	        list: *std.ArrayList(RenderState.Placeholder),
  2582	        alloc: Allocator,
  2583	        stale: *bool,
  2584	        run: ?kitty_gfx.unicode.IncompletePlacement = null,
  2585	        start: usize = 0,
  2586	        end: usize = 0,
  2587	
  2588	        inline fn feed(
  2589	            self: *PlaceholderDecoder,
  2590	            x: usize,
  2591	            style: *const Style,
  2592	            cps: []const u21,
  2593	        ) Allocator.Error!void {
  2594	            const curr: kitty_gfx.unicode.IncompletePlacement = .init(style, cps);
  2595	            if (self.run) |*prev| {
  2596	                if (x == self.end and prev.append(&curr)) {
  2597	                    self.end += 1;
  2598	                    return;
  2599	                }
  2600	                try self.flush();
  2601	            }
  2602	            self.run = curr.start();
  2603	            self.start = x;
  2604	            self.end = x + 1;
  2605	        }
  2606	
  2607	        fn flush(self: *PlaceholderDecoder) Allocator.Error!void {
  2608	            const run = self.run orelse return;
  2609	            self.run = null;
  2610	            self.stale.* = true;
  2611	            try self.list.append(self.alloc, .{
  2612	                .x = @intCast(self.start),
  2613	                .width = @intCast(run.width),
  2614	                .image_id = run.imageId(),
  2615	                .placement_id = run.placement_id orelse 0,
  2616	                .row = run.row.?,
  2617	                .col = run.col.?,
  2618	            });
  2619	        }
