 313	// Grow the texture to the new size, preserving all previously written data.
 314	pub fn grow(self: *Atlas, alloc: Allocator, size_new: u32) Allocator.Error!void {
 315	    const tw = grow_tw;
 316	
 317	    assert(size_new >= self.size);
 318	    if (size_new == self.size) return;
 319	
 320	    // We reserve space ahead of time for the new node, so that we
 321	    // won't have to handle any errors after allocating our new data.
 322	    try tw.check(.ensure_node_capacity);
 323	    try self.nodes.ensureUnusedCapacity(alloc, 1);
 324	
 325	    try tw.check(.alloc_data);
 326	    const data_new = try alloc.alloc(
 327	        u8,
 328	        size_new * size_new * self.format.depth(),
 329	    );
 330	
 331	    // Function is infallible from this point.
 332	    errdefer comptime unreachable;
 333	
 334	    // Keep track of our old data so that we can copy it.
 335	    const data_old = self.data;
 336	    const size_old = self.size;
 337	
 338	    // Update our data and size to our new ones.
 339	    self.data = data_new;
 340	    self.size = size_new;
 341	
 342	    // Free the old data once we're done with it.
 343	    defer alloc.free(data_old);
 344	
 345	    // Zero the new data out and copy the old data over.
 346	    @memset(self.data, 0);
 347	    self.set(.{
 348	        .x = 0, // don't bother skipping border so we can avoid strides
 349	        .y = 1, // skip the first border row
 350	        .width = size_old,
 351	        .height = size_old - 2, // skip the last border row
 352	    }, data_old[size_old * self.format.depth() ..]);
 353	
 354	    // Add the new rectangle for our added righthand space.
 355	    self.nodes.appendAssumeCapacity(.{
 356	        .x = size_old - 1,
 357	        .y = 1,
 358	        .width = size_new - size_old,
 359	    });
 360	
 361	    // We are both modified and resized
 362	    _ = self.modified.fetchAdd(1, .monotonic);
 363	    _ = self.resized.fetchAdd(1, .monotonic);
 364	}
