 325	    try tw.check(.alloc_data);
 326	    const data_new = try alloc.alloc(
 327	        u8,
 328	        size_new * size_new * self.format.depth(),
 329	    );
 330	
 331	    // Function is infallible from this point.
 332	    errdefer comptime unreachable;
 333	
 334	    // Keep track of our old data so that we can copy it.
 335	    const data_old = self.data;
 336	    const size_old = self.size;
 337	
 338	    // Update our data and size to our new ones.
 339	    self.data = data_new;
 340	    self.size = size_new;
 341	
 342	    // Free the old data once we're done with it.
 343	    defer alloc.free(data_old);
